        streamfeature_handlers.push(this._addSysHandler(/** @param {Element} elem */ (elem)=>wrapper(streamfeature_handlers, elem), null, 'stream:features', null, null));
        streamfeature_handlers.push(this._addSysHandler(/** @param {Element} elem */ (elem)=>wrapper(streamfeature_handlers, elem), NS.STREAM, 'features', null, null));
